"use client";
import type { ButtonHTMLAttributes } from "react";
import "./plasma-button.css";

export function PlasmaButton({
  children,
  className = "",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button {...props} type={type} className={`forme-plasma ${className}`}>
      <span className="forme-plasma-glow" aria-hidden="true" />
      <span className="forme-plasma-core">{children}</span>
    </button>
  );
}

@property --forme-plasma-angle {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}
.forme-plasma {
  --forme-plasma-a: #6ee7ff;
  --forme-plasma-b: #8b7bff;
  --forme-plasma-c: #ff7ad9;
  --forme-plasma-ring: conic-gradient(
    from var(--forme-plasma-angle),
    transparent 0deg,
    var(--forme-plasma-a) 60deg,
    var(--forme-plasma-b) 120deg,
    var(--forme-plasma-c) 170deg,
    transparent 220deg,
    transparent 360deg
  );
  position: relative;
  isolation: isolate;
  display: inline-flex;
  padding: 1px;
  border: 0;
  border-radius: 999px;
  background: var(--forme-plasma-ring), #ffffff1f;
  color: #f4f4f5;
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  animation: forme-plasma-spin 6s linear infinite;
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.forme-plasma-glow {
  position: absolute;
  inset: 2px;
  z-index: -1;
  border-radius: inherit;
  background: var(--forme-plasma-ring);
  filter: blur(14px);
  opacity: 0.22;
  transition: opacity 0.4s;
}
.forme-plasma-core {
  display: inline-flex;
  align-items: center;
  height: 46px;
  padding: 0 26px;
  border-radius: inherit;
  background: linear-gradient(180deg, #19191d, #0b0b0d);
  box-shadow: inset 0 1px 0 #ffffff14;
}
.forme-plasma:hover,
.forme-plasma:focus-visible {
  animation-duration: 2.4s;
}
.forme-plasma:hover .forme-plasma-glow,
.forme-plasma:focus-visible .forme-plasma-glow {
  opacity: 0.55;
}
.forme-plasma:active {
  transform: scale(0.98);
}
.forme-plasma:focus-visible {
  outline: 2px solid #f4f4f5;
  outline-offset: 4px;
}
.forme-plasma:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  animation: none;
}
@keyframes forme-plasma-spin {
  to {
    --forme-plasma-angle: 360deg;
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-plasma,
  .forme-plasma:hover {
    animation: none;
    transition: none;
  }
  .forme-plasma-glow {
    transition: none;
  }
}
